INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8632, 'ធីតាជិះកង់ \(15\ \text{km/h}\) លក្ខិណាដើរ \(4\ \text{km/h}\) ចេញពីផ្ទះម៉ោងជាមួយគ្នាទៅសាលា។ ធីតាដល់សាលារួចត្រឡប់មកវិញ ជួបលក្ខិណាត្រង់បង្គោល \(10\ \text{km}\) (គិតពីផ្ទះ)។ ចម្ងាយពីផ្ទះទៅសាលាគឺ៖', 'g8-051467b86c.svg', '["\\(26\\ \\text{km}\\)", "\\(23.75\\ \\text{km}\\)", "\\(20\\ \\text{km}\\)", "\\(30\\ \\text{km}\\)"]', 1, NULL, 3, 'mcq', 'រយៈពេលលក្ខិណា \(10/4\) ស្មើពេលធីតា \((2x-10)/15\) នាំឱ្យ \(8x - 40 = 150 \Rightarrow x = 23.75\ \text{km}\)។', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8633, 'ក្រុមស្ត្រីហាត់ប្រាណ ៖ «ចំនួនពួកយើង បូកចំនួនពួកយើង បូកពាក់កណ្តាលពួកយើង បូក \(\dfrac{1}{4}\) នៃពួកយើង និងស៊ីថាម្នាក់ទៀត ស្មើ \(100\) នាក់»។ ចំនួនស្ត្រីក្នុងក្រុមគឺ៖', NULL, '["\\(40\\) នាក់", "\\(33\\) នាក់", "\\(36\\) នាក់", "\\(45\\) នាក់"]', 2, NULL, 3, 'mcq', '\(x + x + \dfrac{x}{2} + \dfrac{x}{4} + 1 = 100 \Rightarrow \dfrac{11x}{4} = 99 \Rightarrow x = 36\) នាក់។', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8634, 'អ្នកថ្មើរជើងម្នាក់ឡើងភ្នំក្នុងល្បឿនមធ្យម \(300\ \text{m/h}\) និងចុះមកវិញក្នុងល្បឿន \(450\ \text{m/h}\)។ ចេញដំណើរម៉ោង \(7\text{h}\ 00\) ដល់កន្លែងដើមវិញម៉ោង \(18\text{h}\ 45\) ដោយសម្រាកលើកំពូលភ្នំ \(4\text{h}\ 15\)។ ចម្ងាយផ្លូវពីជើងភ្នំដល់កំពូលភ្នំគឺ៖', NULL, '["\\(1\\,350\\ \\text{m}\\)", "\\(2\\,250\\ \\text{m}\\)", "\\(1\\,800\\ \\text{m}\\)", "\\(900\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', 'ពេលធ្វើដំណើរសរុប \(11.75 - 4.25 = 7.5\ \text{h}\)។ \(\dfrac{d}{300} + \dfrac{d}{450} = 7.5 \Rightarrow \dfrac{5d}{900} = 7.5 \Rightarrow d = 1\,350\ \text{m}\)។', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
