INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8635, 'ចតុកោណកែងមួយមានទទឹង \(2\ \text{cm}\) និងបណ្តោយ \(9\ \text{cm}\)។ បើគេបង្កើនទទឹង \(1\ \text{cm}\) និងបណ្តោយ \(x\ \text{cm}\) ផ្ទៃក្រឡាថ្មីស្មើពីរដងនៃផ្ទៃក្រឡាចាស់។ តម្លៃនៃ \(x\) គឺ៖', 'g8-a9e58c6180.svg', '["\\(4.5\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(3\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', 'ផ្ទៃចាស់ \(18\ \text{cm}^2\)។ ផ្ទៃថ្មី \(3(9 + x) = 36 \Rightarrow 9 + x = 12 \Rightarrow x = 3\ \text{cm}\)។', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 1, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
