ខ. \(3x - 2x = -3 - 5\) ; \(x = -8\) (2 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ \(3(-8) + 5 = -19 = 2(-8) - 3\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'easy', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8638, 'ដោះស្រាយសមីការ ក. \(\dfrac{2x}{5}+\dfrac{x}{4} = \dfrac{26}{5}\) ខ. \(\dfrac{3}{5}x+3 = \dfrac{1}{5}x-7\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គុណអង្គទាំងពីរនឹង \(20\) ៖ \(8x + 5x = 104\) (1 ពិន្ទុ)
\(13x = 104 \Rightarrow x = 8\) (1 ពិន្ទុ)
ខ. \(\dfrac{3}{5}x - \dfrac{1}{5}x = -7 - 3\) (1 ពិន្ទុ)
\(\dfrac{2}{5}x = -10\) (1 ពិន្ទុ)
\(x = -10 \times \dfrac{5}{2} = -25\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8639, 'ដោះស្រាយសមីការ ក. \(8-2(x+1) = -3x+1\) ខ. \(4(a+6) = 24a\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(8 - 2x - 2 = -3x + 1\) (1 ពិន្ទុ)
\(-2x + 6 = -3x + 1 \Rightarrow x = -5\) (2 ពិន្ទុ)
ខ. \(4a + 24 = 24a \Rightarrow 20a = 24\) (1 ពិន្ទុ)
\(a = \dfrac{6}{5} = 1.2\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8640, 'ដោះស្រាយ ក. \(-3(2n-5) = \dfrac{1}{2}(-12n+30)\) ខ. \(-3y+5(6-y) = 4(1-2y)\) ហើយប្រាប់ចំនួនឫស។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អង្គទី ១ \(-6n + 15\) ; អង្គទី ២ \(-6n + 15\) (1 ពិន្ទុ)
សមីការពិតគ្រប់តម្លៃ \(n\) (ឫសច្រើនរាប់មិនអស់) (1 ពិន្ទុ)
ខ. អង្គទី ១ \(-3y + 30 - 5y = -8y + 30\) (1 ពិន្ទុ)
អង្គទី ២ \(4 - 8y\) នាំឱ្យ \(30 = 4\) មិនពិត (1 ពិន្ទុ)
ដូចនេះ សមីការគ្មានឫស (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8641, 'ដោះស្រាយ ក. \((a+12)(a-4) = 2a(a-4)\) ខ. \((2x-1)^{2} = (x+3)^{2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((a-4)[(a+12) - 2a] = 0 \Rightarrow (a-4)(12-a) = 0\) (1 ពិន្ទុ)
\(a = 4\) ឬ \(a = 12\) (1 ពិន្ទុ)
ខ. \((2x-1)^2 - (x+3)^2 = 0 \Rightarrow [(2x-1)+(x+3)][(2x-1)-(x+3)] = 0\) (1 ពិន្ទុ)
\((3x+2)(x-4) = 0\) (1 ពិន្ទុ)
\(x = -\dfrac{2}{3}\) ឬ \(x = 4\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'medium', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8642, 'ដោះស្រាយ ក. \(4x^{2}(x+1) = 9(x+1)\) ខ. \((x-7)^{2} = (5x-6)^{2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((x+1)(4x^2 - 9) = 0 \Rightarrow (x+1)(2x-3)(2x+3) = 0\) (1 ពិន្ទុ)
\(x = -1,\ x = \dfrac{3}{2},\ x = -\dfrac{3}{2}\) (1 ពិន្ទុ)
ខ. \([(x-7)+(5x-6)][(x-7)-(5x-6)] = 0\) (1 ពិន្ទុ)
\((6x-13)(-4x-1) = 0\) (1 ពិន្ទុ)
\(x = \dfrac{13}{6}\) ឬ \(x = -\dfrac{1}{4}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8643, 'វិបុលដោះស្រាយ \(6m - 15 = 10m - 25\) ដោយដាក់កត្តា \(3(2m-5) = 5(2m-5)\) រួចចែកនឹង \(2m-5\) បាន \(3 = 5\)។ ក. រកកំហុស។ ខ. ដោះស្រាយឱ្យត្រឹមត្រូវ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កំហុស ៖ ចែកអង្គទាំងពីរនឹង \(2m-5\) ដែលអាចស្មើសូន្យ (បាត់បង់ឫស) (1 ពិន្ទុ)
ខ. \(3(2m-5) - 5(2m-5) = 0\) (1 ពិន្ទុ)
\(-2(2m-5) = 0\) (1 ពិន្ទុ)
\(2m - 5 = 0\) (1 ពិន្ទុ)
\(m = \dfrac{5}{2} = 2.5\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8644, 'ក. រកបីចំនួនគត់គូតគ្នាដែលផលបូក \(-12\)។ ខ. រកប្រាំចំនួនគត់តគ្នាដែលផលបូក \(520\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(x, x+2, x+4\) ; \(3x + 6 = -12\) (1 ពិន្ទុ)
\(x = -6\) ; ចំនួនគឺ \(-6, -4, -2\) (1 ពិន្ទុ)
ខ. តាង \(n, n+1, \ldots, n+4\) ; \(5n + 10 = 520\) (1 ពិន្ទុ)
\(n = 102\) (1 ពិន្ទុ)
\(102, 103, 104, 105, 106\) (ផលបូក \(520\)) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8645, 'សូផាតអាយុ \(51\) ឆ្នាំ រស្មីអាយុ \(21\) ឆ្នាំ។ ក. សរសេរសមីការរកចំនួនឆ្នាំ \(t\) ដែលសូផាតមានអាយុស្មើពីរដងរស្មី។ ខ. ដោះស្រាយ និងផ្ទៀងផ្ទាត់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(51 + t = 2(21 + t)\) (1 ពិន្ទុ)
ខ. \(51 + t = 42 + 2t\) (1 ពិន្ទុ)
\(t = 9\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ សូផាត \(60\) រស្មី \(30\) (1 ពិន្ទុ)
\(60 = 2 \times 30\) ពិត (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'hard', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8646, 'ចតុកោណកែងមានបរិមាត្រ \(148\ \text{cm}\) ហើយបណ្តោយស្មើបីដងទទឹងថែម \(17\ \text{cm}\)។ ក. សរសេរសមីការ។ ខ. រកទទឹង និងបណ្តោយ។ គ. គណនាផ្ទៃក្រឡា។', 'g8-3db81f75b2.svg', '[]', 0, NULL, 5, 'writing', 'ក. តាង \(b\) ជាទទឹង បណ្តោយ \(3b + 17\) ; \(2(3b + 17 + b) = 148\) (1 ពិន្ទុ)
ខ. \(8b + 34 = 148 \Rightarrow 8b = 114 \Rightarrow b = 14.25\ \text{cm}\) (1 ពិន្ទុ)
បណ្តោយ \(3(14.25) + 17 = 59.75\ \text{cm}\) (1 ពិន្ទុ)
គ. \(\mathcal{A} = 14.25 \times 59.75\) (1 ពិន្ទុ)
\(= 851.4375\ \text{cm}^2\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8647, 'ចតុកោណកែងទទឹង \(2\ \text{cm}\) បណ្តោយ \(9\ \text{cm}\)។ បង្កើនទទឹង \(1\ \text{cm}\) និងបណ្តោយ \(x\ \text{cm}\) ផ្ទៃក្រឡាថ្មីស្មើពីរដងនៃផ្ទៃក្រឡាចាស់។ ក. រកផ្ទៃក្រឡាចាស់។ ខ. សរសេរសមីការ។ គ. រក \(x\)។', 'g8-a9e58c6180.svg', '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃចាស់ \(\mathcal{A}_1 = 9 \times 2 = 18\ \text{cm}^2\) (1 ពិន្ទុ)
ខ. វិមាត្រថ្មី \(3\) និង \(9 + x\) ; \(3(9 + x) = 2 \times 18 = 36\) (2 ពិន្ទុ)
គ. \(27 + 3x = 36 \Rightarrow 3x = 9\) (1 ពិន្ទុ)
\(x = 3\ \text{cm}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8648, 'ធីតាជិះកង់ \(15\ \text{km/h}\) លក្ខិណាដើរ \(4\ \text{km/h}\) ចេញពីផ្ទះម៉ោងជាមួយគ្នាទៅសាលា។ ធីតាដល់សាលារួចត្រឡប់មកវិញ ជួបលក្ខិណាត្រង់បង្គោល \(10\ \text{km}\) (គិតពីផ្ទះ)។ រកចម្ងាយពីផ្ទះទៅសាលា។', 'g8-051467b86c.svg', '[]', 0, NULL, 5, 'writing', 'តាង \(x\) ជាចម្ងាយពីផ្ទះទៅសាលា \((x > 10)\) (1 ពិន្ទុ)
ពេលលក្ខិណាដើរ \(t_1 = \dfrac{10}{4}\ \text{h}\) (1 ពិន្ទុ)
ធីតាចរបាន \(x + (x - 10) = 2x - 10\) ; ពេលធីតា \(t_2 = \dfrac{2x - 10}{15}\ \text{h}\) (1 ពិន្ទុ)
សមីការ ៖ \(\dfrac{10}{4} = \dfrac{2x - 10}{15} \Rightarrow 150 = 8x - 40\) (1 ពិន្ទុ)
\(8x = 190 \Rightarrow x = 23.75\ \text{km}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8649, 'ក្រុមស្ត្រីហាត់ប្រាណមួយ ៖ «ចំនួនពួកយើង បូកចំនួនពួកយើង បូកពាក់កណ្តាល បូក \(\dfrac{1}{4}\) នៃពួកយើង រួមទាំងស៊ីថាម្នាក់ទៀត ស្មើ \(100\) នាក់»។ រកចំនួនស្ត្រីក្នុងក្រុម។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(x\) ជាចំនួនស្ត្រីក្នុងក្រុម (1 ពិន្ទុ)
\(x + x + \dfrac{x}{2} + \dfrac{x}{4} + 1 = 100\) (1 ពិន្ទុ)
\(\dfrac{11x}{4} = 99 \Rightarrow 11x = 396\) (1 ពិន្ទុ)
\(x = 36\) នាក់ (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(36 + 36 + 18 + 9 + 1 = 100\) (ពិត) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', 'pisa', 0, '8', 'សមីការដឺក្រេទី ១ មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8650, 'អ្នកថ្មើរជើងឡើងភ្នំ \(300\ \text{m/h}\) ចុះ \(450\ \text{m/h}\) ចេញម៉ោង \(7\text{h}\ 00\) ត្រឡប់ដល់វិញ \(18\text{h}\ 45\) សម្រាក \(4\text{h}\ 15\)។ រកចម្ងាយផ្លូវពីជើងភ្នំដល់កំពូល។', NULL, '[]', 0, NULL, 5, 'writing', 'ពេលសរុប \(18.75 - 7 = 11.75\ \text{h}\) ; ដកសម្រាក \(4.25\ \text{h}\) នៅ \(7.5\ \text{h}\) (1 ពិន្ទុ)
តាង \(d\) ជាចម្ងាយ (m) ៖ \(\dfrac{d}{300} + \dfrac{d}{450} = 7.5\) (1 ពិន្ទុ)
